// Hitung download -> lempar ke APK
// STRATEGI BARU (anti scanner ngintip):
// /download TIDAK langsung redirect & TIDAK langsung hitung.
// Dia balikin halaman HTML kecil yang:
//   1. jalanin JS -> panggil /api/dl-hit (hitung +1, anti-dobel via localStorage token)
//   2. redirect ke APK
// Bot/scanner yang cuma "ngintip" link = ambil HTML doang, GAK jalanin JS -> GAK terhitung.
// Browser asli = jalanin JS -> terhitung 1x. localStorage cegah dobel walau di-refresh.
async function apiDownload(request, env) {
  await ensureCounters(env);

  const target = CONFIG.DIRECT_APK_URL ||
    `https://github.com/${CONFIG.GITHUB_OWNER}/${CONFIG.GITHUB_REPO}/releases/latest/download/${CONFIG.APK_FILE}`;

  const html = `<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>Mengunduh APK EMAKBET…</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{background:#101916;color:#d7ffe9;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
       min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px}
  .box{max-width:360px}
  .logo{width:76px;height:76px;border-radius:18px;background:#1e2f2b;margin:0 auto 18px;
        display:flex;align-items:center;justify-content:center;font-size:38px;
        box-shadow:0 8px 30px rgba(0,255,140,.15)}
  h1{font-size:19px;margin-bottom:8px;color:#eafff5}
  p{font-size:14px;color:#8fd9b3;line-height:1.5}
  .spin{width:44px;height:44px;border:4px solid rgba(0,255,140,.15);border-top-color:#00e676;
        border-radius:50%;margin:22px auto;animation:r .8s linear infinite}
  @keyframes r{to{transform:rotate(360deg)}}
  a.fb{display:inline-block;margin-top:18px;color:#00e676;font-size:13px;text-decoration:underline}
  .muted{font-size:12px;color:#5e8f74;margin-top:10px}
</style>
</head>
<body>
  <div class="box">
    <div class="logo">📥</div>
    <h1>Menyiapkan unduhan…</h1>
    <div class="spin"></div>
    <p>APK <b>EMAKBET</b> sedang diunduh otomatis.<br>Tunggu sebentar ya.</p>
    <a class="fb" id="fb" href="${target}">Klik di sini kalau tidak mulai otomatis</a>
    <div class="muted">Aman • Bebas virus • Versi terbaru</div>
  </div>
<script>
(function(){
  var APK = ${JSON.stringify(target)};
  var HIT = "/api/dl-hit";

  // mulai unduhan APK (redirect)
  function go(){
    // pakai lokasi assign biar HP mulai unduh APK
    try { window.location.replace(APK); }
    catch(e){ window.location.href = APK; }
  }

  // hitung download 1x aja per device (anti-dobel via localStorage)
  // token disimpan 6 jam. kalau device ini udah kehitung dalam 6 jam -> skip hitung.
  function countOnce(cb){
    var KEY = "emakbet_dl_ts";
    var now = Date.now();
    var SIX_H = 6*3600*1000;
    var last = 0;
    try { last = parseInt(localStorage.getItem(KEY)||"0",10); } catch(e){}

    if (last && (now - last) < SIX_H){
      // udah kehitung dalam 6 jam -> jangan hitung lagi, langsung unduh
      cb();
      return;
    }
    // catat waktu sekarang biar ngintip/refresh gak dobel
    try { localStorage.setItem(KEY, String(now)); } catch(e){}

    // kirim hit ke server (hitung +1). Apapun hasilnya, tetap lanjut unduh.
    var done=false;
    function once(){ if(done) return; done=true; cb(); }
    // timeout jaga2 kalau server lambat (1.5 detik) -> tetap unduh
    setTimeout(once, 1500);
    try{
      fetch(HIT, {method:"POST", cache:"no-store", keepalive:true})
        .then(function(){ once(); })
        .catch(function(){ once(); });
    }catch(e){ once(); }
  }

  // jalan setelah halaman render (scanner yg ngintip gak sampai sini)
  countOnce(go);
})();
</script>
</body>
</html>`;

  return new Response(html, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store, no-cache, must-revalidate",
    },
  });
}

