// Helper: SHA-256 -> hex (buat sidik jari device)
async function sha256hex(str) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(str));
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join("").slice(0, 32);
}

/* ========================= FIREBASE FCM (HTTP v1) ========================= */

// Kirim 1 notif ke 1 token. return true kalau sukses.
async function fcmSend(projectId, access, token, n) {
  // PENTING: pakai DATA MESSAGE MURNI (tanpa blok "notification").
  // Kenapa? Kalau pakai "notification", saat APK ketutup yg render adl SISTEM HP,
  // dan icon bisa salah/kosong. Dengan data message, MyFirebaseService di APK yg
  // SELALU render (foreground & background) -> icon dijamin ic_notif yg bener.
  const msg = {
    message: {
      token,
      // semua info dikirim lewat "data" -> dibaca MyFirebaseService.onMessageReceived
      data: {
        title: String(n.title || "EMAKBET"),
        body: String(n.body || ""),
        click_url: String(n.click || ""),
        image: String(n.image || ""),
      },
      android: {
        priority: "HIGH",
        // TTL biar notif tetap dikirim walau HP sempat offline
        ttl: "86400s",
      },
    },
  };
  const r = await fetch(`https://fcm.googleapis.com/v1/projects/${projectId}/messages:send`, {
    method: "POST",
    headers: { Authorization: `Bearer ${access}`, "Content-Type": "application/json" },
    body: JSON.stringify(msg),
  });

  if (r.ok) return { ok: true, uninstall: false };

  // GAGAL -> cari tau ALASANNYA. Ini penting biar kita nggak salah nuduh "uninstall".
  // Firebase cuma kasih tanda token BENERAN hilang (APK dihapus) lewat:
  //   - HTTP 404 + errorCode "UNREGISTERED"  -> token sudah tidak terdaftar (APK dihapus/data dibersihkan)
  //   - HTTP 400 + "INVALID_ARGUMENT" pada token -> token rusak/palsu (tidak akan pernah bisa dipakai)
  // Selain itu (401/403/429/500/503/timeout) = MASALAH SEMENTARA, jangan tandai uninstall.
  let errCode = "", errStatus = "";
  try {
    const j = await r.json();
    errStatus = String(j?.error?.status || "");
    const details = j?.error?.details || [];
    for (const d of details) {
      if (d?.errorCode) { errCode = String(d.errorCode); break; }
    }
  } catch (e) { /* body bukan JSON -> biarkan kosong */ }

  // HANYA dua kondisi ini yang dianggap APK BENERAN sudah tidak ada di HP:
  const benarUninstall =
    (r.status === 404 && errCode === "UNREGISTERED") ||
    (r.status === 400 && errCode === "INVALID_ARGUMENT");

  return { ok: false, uninstall: benarUninstall, http: r.status, code: errCode || errStatus };
}

// Ambil access token Google via JWT service account (cache 55 menit)
async function getGoogleToken(env) {
  const now = Date.now();
  if (TOKEN_CACHE.token && now - TOKEN_CACHE.at < 55 * 60 * 1000) return TOKEN_CACHE.token;

  const sa = JSON.parse(env.FIREBASE_SA_JSON);
  const iat = Math.floor(now / 1000);
  const claim = {
    iss: sa.client_email,
    scope: "https://www.googleapis.com/auth/firebase.messaging",
    aud: "https://oauth2.googleapis.com/token",
    iat,
    exp: iat + 3600,
  };
  const header = { alg: "RS256", typ: "JWT" };
  const unsigned = `${b64url(JSON.stringify(header))}.${b64url(JSON.stringify(claim))}`;

  const key = await importPrivateKey(sa.private_key);
  const sig = await crypto.subtle.sign(
    "RSASSA-PKCS1-v1_5", key, new TextEncoder().encode(unsigned)
  );
  const jwt = `${unsigned}.${b64urlBytes(new Uint8Array(sig))}`;

  const res = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
      assertion: jwt,
    }),
  });
  const d = await res.json();
  if (!d.access_token) throw new Error("no_access_token: " + JSON.stringify(d));
  TOKEN_CACHE = { at: now, token: d.access_token };
  return d.access_token;
}

async function importPrivateKey(pem) {
  const clean = pem.replace(/-----BEGIN PRIVATE KEY-----/, "")
    .replace(/-----END PRIVATE KEY-----/, "").replace(/\s/g, "");
  const bin = Uint8Array.from(atob(clean), c => c.charCodeAt(0));
  return crypto.subtle.importKey(
    "pkcs8", bin.buffer,
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false, ["sign"]
  );
}
function b64url(s) {
  return btoa(unescape(encodeURIComponent(s))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function b64urlBytes(bytes) {
  let s = ""; for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/* ============================== HELPERS ================================== */
function json(o, s = 200) {
  return new Response(JSON.stringify(o), { status: s, headers: { "Content-Type": "application/json; charset=utf-8" } });
}
function html(s, st = 200) {
  return new Response(s, { status: st, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
}
function cors(r) {
  const h = new Headers(r.headers);
  h.set("Access-Control-Allow-Origin", "*");
  h.set("Access-Control-Allow-Methods", "GET,POST,OPTIONS");
  h.set("Access-Control-Allow-Headers", "Content-Type,X-Admin-Key,X-App-Key");
  return new Response(r.body, { status: r.status, headers: h });
}
async function safeJson(r) { try { return await r.json(); } catch { return {}; } }
function clean(v, max) { return v == null ? "" : String(v).trim().slice(0, max || 200); }
function num(v) { const n = parseInt(v, 10); return isNaN(n) ? 0 : n; }
function chunk(a, n) { const o = []; for (let i = 0; i < a.length; i += n) o.push(a.slice(i, i + n)); return o; }
function appKeyOK(r, b) {
  if (!CONFIG.APP_KEY) return true;
  return (r.headers.get("X-App-Key") || b?.app_key || "") === CONFIG.APP_KEY;
}
// ====== AUTH via Google Authenticator (TOTP) + token sesi ======
// LOGIN: user kirim kode 6 digit -> verifikasi TOTP -> balikin token sesi
async function apiLogin(request, env) {
  if (!env.TOTP_SECRET) {
    return json({ ok: false, error: "no_totp", detail: "TOTP_SECRET belum di-set di worker. Jalankan: wrangler secret put TOTP_SECRET" }, 400);
  }
  const b = await safeJson(request);
  const res = await verifyTOTP(b.code, env);
  if (!res.ok) return json({ ok: false, error: res.err, detail: "Kode salah / kadaluarsa. Cek Google Authenticator." }, 401);
  const token = await makeSession(env);
  return json({ ok: true, token, expires_h: CONFIG.SESSION_HOURS || 12 });
}

async function totpCheck(env) {
  const secret = (env && env.TOTP_SECRET) || "";
  if (!secret) {
    return json({
      ok: false,
      status: "TOTP_SECRET KOSONG",
      artinya: "Secret belum di-set di worker. Jalankan: wrangler secret put TOTP_SECRET",
    });
  }
  const key = base32Decode(secret);
  const step = Math.floor(Date.now() / 1000 / 30);
  const kodes = {
    sebelumnya: await totpAt(key, step - 1),
    sekarang: await totpAt(key, step),
    berikutnya: await totpAt(key, step + 1),
  };
  return json({
    ok: true,
    status: "TOTP_SECRET terbaca ✅",
    panjang_secret: secret.length,
    secret_awal: secret.slice(0, 4) + "..." + secret.slice(-4),
    kode_yang_worker_harapkan: kodes,
    cara_pakai: "Bandingkan 'sekarang' dgn kode di Google Authenticator HP. Kalau BEDA = secret worker & HP tidak sama.",
    waktu_server: new Date().toISOString(),
  });
}

// --- Cek kesiapan Firebase (buat diagnosa push notif) ---
// Buka: https://[worker].workers.dev/api/notif-check
async function notifCheck(env) {
  const raw = (env && env.FIREBASE_SA_JSON) || "";

  // 1) Kunci ada nggak?
  if (!raw) {
    return json({
      ok: false,
      status: "FIREBASE_SA_JSON KOSONG",
      artinya: "Kunci Firebase belum di-set. Masukkan via wrangler secret put FIREBASE_SA_JSON atau lewat dashboard Cloudflare (Settings > Variables and Secrets).",
    });
  }

  // 2) Isinya JSON valid nggak?
  let sa;
  try {
    sa = JSON.parse(raw);
  } catch (e) {
    return json({
      ok: false,
      status: "FIREBASE_SA_JSON RUSAK ❌",
      artinya: "Kunci kebaca, tapi isinya bukan JSON yang benar. Kemungkinan pas paste ada bagian kepotong / kurang lengkap. Copy ULANG SELURUH isi file .json (dari { sampai }) lalu paste lagi.",
      panjang_teks: raw.length,
    });
  }

  // 3) Field wajib lengkap nggak?
  const wajib = ["project_id", "client_email", "private_key"];
  const kurang = wajib.filter((k) => !sa[k]);
  if (kurang.length) {
    return json({
      ok: false,
      status: "FIREBASE_SA_JSON KURANG FIELD ❌",
      field_yang_hilang: kurang,
      artinya: "JSON valid tapi ada bagian penting yang hilang. Pastikan lu pakai file service account (Generate new private key), BUKAN file google-services.json.",
    });
  }

  // 4) Tes beneran: coba ambil access token ke Google.
  //    Ini bukti paling kuat kalau kunci beneran sakti & bisa kirim notif.
  let tokenTest;
  try {
    const access = await getGoogleToken(env);
    tokenTest = access
      ? "✅ BERHASIL ambil access token ke Google. Sisi worker 100% siap kirim notif."
      : "❌ Access token kosong (aneh, coba cek ulang kunci).";
  } catch (e) {
    return json({
      ok: false,
      status: "KUNCI DITOLAK GOOGLE ❌",
      project_id: sa.project_id,
      client_email: sa.client_email,
      detail_error: String(e?.message || e),
      artinya: "JSON-nya bener, tapi Google nolak. Biasanya: kunci udah di-revoke di Firebase, atau jam server bermasalah. Coba Generate new private key yang baru di Firebase, masukkan lagi.",
    });
  }

  return json({
    ok: true,
    status: "FIREBASE SIAP ✅",
    project_id: sa.project_id,
    client_email: sa.client_email,
    tes_akses_google: tokenTest,
    catatan_penting: "Sisi WORKER sudah siap. TAPI notif tetap butuh APK yang bisa terima FCM (App Inventor WebView polos TIDAK bisa). Kalau device di panel fcm_token-nya kosong, notif tidak akan sampai ke HP.",
    waktu_server: new Date().toISOString(),
  });
}

// --- Base32 decode (buat secret Google Authenticator) ---
function base32Decode(s) {
  const alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  s = String(s || "").toUpperCase().replace(/=+$/, "").replace(/\s/g, "");
  let bits = "", out = [];
  for (const c of s) {
    const v = alpha.indexOf(c);
    if (v < 0) continue;
    bits += v.toString(2).padStart(5, "0");
  }
  for (let i = 0; i + 8 <= bits.length; i += 8) out.push(parseInt(bits.slice(i, i + 8), 2));
  return new Uint8Array(out);
}

// --- HMAC-SHA1 (Web Crypto) ---
async function hmacSha1(keyBytes, msgBytes) {
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: "HMAC", hash: "SHA-1" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, msgBytes);
  return new Uint8Array(sig);
}

// --- hitung kode TOTP 6 digit utk counter tertentu ---
async function totpAt(secretBytes, counter) {
  const buf = new ArrayBuffer(8), dv = new DataView(buf);
  dv.setUint32(0, Math.floor(counter / 0x100000000));
  dv.setUint32(4, counter >>> 0);
  const h = await hmacSha1(secretBytes, new Uint8Array(buf));
  const off = h[h.length - 1] & 0xf;
  const bin = ((h[off] & 0x7f) << 24) | (h[off + 1] << 16) | (h[off + 2] << 8) | h[off + 3];
  return (bin % 1000000).toString().padStart(6, "0");
}

// --- verifikasi kode 6 digit (toleransi ±1 langkah = ±30 detik) ---
async function verifyTOTP(code, env) {
  const secret = (env && env.TOTP_SECRET) || "";
  if (!secret) return { ok: false, err: "no_totp" };
  code = String(code || "").replace(/\D/g, "");
  if (code.length !== 6) return { ok: false, err: "bad_code" };
  const key = base32Decode(secret);
  const step = Math.floor(Date.now() / 1000 / 30);
  for (let w = -1; w <= 1; w++) {
    if (await totpAt(key, step + w) === code) return { ok: true };
  }
  return { ok: false, err: "wrong_code" };
}

// --- bikin token sesi bertanda tangan (payload.exp . signature) ---
async function makeSession(env) {
  const secret = (env && env.TOTP_SECRET) || "";
  const exp = Date.now() + (CONFIG.SESSION_HOURS || 12) * 3600 * 1000;
  const payload = "s" + exp;
  const key = base32Decode(secret);
  const sig = await hmacSha1(key, new TextEncoder().encode(payload));
  const hex = [...sig].map(b => b.toString(16).padStart(2, "0")).join("");
  return payload + "." + hex;
}

// cek token sesi (tanda tangan + belum kadaluarsa)
async function checkSession(tok, env) {
  try {
    const secret = (env && env.TOTP_SECRET) || "";
    if (!secret || !tok || tok.indexOf(".") < 0) return false;
    const [payload, hex] = tok.split(".");
    if (payload[0] !== "s") return false;
    const exp = parseInt(payload.slice(1), 10);
    if (!exp || Date.now() > exp) return false;
    const key = base32Decode(secret);
    const sig = await hmacSha1(key, new TextEncoder().encode(payload));
    const want = [...sig].map(b => b.toString(16).padStart(2, "0")).join("");
    return want === hex;
  } catch { return false; }
}
function startOfTodayWIB() {
  const o = 7 * 3600 * 1000, d = new Date(Date.now() + o);
  d.setUTCHours(0, 0, 0, 0); return d.getTime() - o;
}

